    .readout{left:18px;bottom:16px;font-size:10px}
    .hint{display:none}
  }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div class="ui" aria-hidden="true">
  <div class="hdr">
    <div class="eyebrow">Molecular viewport <b>&middot;</b> 001</div>
    <h1>B-Form DNA</h1>
    <div class="sub">10 bp / turn &middot; 3.4 &Aring; rise &middot; right-handed helix</div>
    <div class="legend">
      <span><i class="dot a"></i>strand a &middot; 5&prime;&rarr;3&prime;</span>
      <span><i class="dot b"></i>strand b &middot; 3&prime;&rarr;5&prime;</span>
    </div>
  </div>
  <div class="readout" id="readout"></div>
  <div class="hint">drag &mdash; rotate<br>wheel &mdash; zoom<br>hover &mdash; inspect pair</div>
</div>

<script>
(() => {
'use strict';

const TAU = Math.PI * 2;
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const readout = document.getElementById('readout');
const FONT = '"Iosevka","Cascadia Code","JetBrains Mono","SF Mono",ui-monospace,Menlo,Consolas,monospace';

// ---------- model (B-DNA proportions, lightly stylised) ----------
const N = 44;                       // base pairs
const DY = 27;                      // rise per bp, world units
const R = 90;                       // helix radius, world units
const STEP = TAU / 10;              // 10 bp per turn
const HALF_H = (N - 1) / 2 * DY;
const FOCAL = 1200;
const SWEEP_PERIOD = 7.5;
const BASE_SPEED = matchMedia('(prefers-reduced-motion: reduce)').matches ? 0.03 : 0.22;

// ---------- palette ----------
const BG = '#0a0d10';
const HUE = [16, 168];              // strand A warm coral / strand B teal
const SAT = [64, 46];
const BASES = [['A','T'],['T','A'],['G','C'],['C','G']];
const pairOf = i => BASES[(i * 7 + 3) % 4];
const jitter = i => { const v = Math.sin(i * 127.1 + 3.7) * 43758.5453; return (v - Math.floor(v)) * 2 - 1; };
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const strandColor = (st, fog, a, lShift = 0) =>
  `hsla(${HUE[st]},${SAT[st]}%,${(50 + 16 * fog + lShift).toFixed(1)}%,${Math.min(a, 1).toFixed(3)})`;

// ---------- state ----------
let W = 0, H = 0, baseScale = 1, vg = null, gridLayer = null;
let rot = 0.8, rotVel = BASE_SPEED;
let tilt = 0, tiltTarget = 0, sinT = 0, cosT = 1;
let zoom = 1, zoomTarget = 1;
let sweepT = 1.2;
let hoverIdx = -1, mx = -1e4, my = -1e4, hasMouse = false;
const pointers = new Map();
let dragging = false, lastX = 0, lastY = 0, pinchDist = 0;

// pre-allocated projections for the two strands
const pA = [], pB = [];
for (let i = 0; i < N; i++){ pA.push({x:0,y:0,s:0,z:0}); pB.push({x:0,y:0,s:0,z:0}); }

function projXY(x3, y3, z3){
  const y2 = y3 * cosT - z3 * sinT;
  const z  = y3 * sinT + z3 * cosT;   // +z toward the viewer
  const s  = baseScale * zoom * FOCAL / (FOCAL - z);
  return { x: W / 2 + x3 * s, y: H / 2 + y2 * s, s, z };
}

function computePoints(){
  for (let i = 0; i < N; i++){
    const a = rot + i * STEP;
    const y3 = (i - (N - 1) / 2) * DY;
    let p = projXY(R * Math.sin(a), y3, R * Math.cos(a));
    pA[i].x = p.x; pA[i].y = p.y; pA[i].s = p.s; pA[i].z = p.z;
    p = projXY(-R * Math.sin(a), y3, -R * Math.cos(a));
    pB[i].x = p.x; pB[i].y = p.y; pB[i].s = p.s; pB[i].z = p.z;
  }
}

// scan position in world-y, travels bottom -> top then rests
function sweepY(t){
  const p = (t % SWEEP_PERIOD) / SWEEP_PERIOD;
  if (p >= 0.78) return null;
  const q = p / 0.78, e = q * q * (3 - 2 * q);
  return HALF_H - e * 2 * HALF_H;
}

// ---------- sizing ----------
function resize(){
  const dpr = Math.min(devicePixelRatio || 1, 2);
  W = innerWidth; H = innerHeight;
  canvas.width = W * dpr; canvas.height = H * dpr;
  canvas.style.width = W + 'px'; canvas.style.height = H + 'px';
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  baseScale = (H * 0.82) / (N * DY);
  vg = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.36, W / 2, H / 2, Math.hypot(W, H) * 0.62);
  vg.addColorStop(0, 'rgba(5,8,11,0)');
  vg.addColorStop(1, 'rgba(3,5,8,0.42)');
  // faint measurement-dot grid, pre-rendered once per resize
  gridLayer = document.createElement('canvas');
  gridLayer.width = W * dpr; gridLayer.height = H * dpr;
  const g = gridLayer.getContext('2d');
  g.scale(dpr, dpr);
  g.fillStyle = 'rgba(148,170,180,0.055)';
  for (let y = 14; y < H; y += 28)
    for (let x = 14; x < W; x += 28){ g.beginPath(); g.arc(x, y, 1, 0, TAU); g.fill(); }
}
addEventListener('resize', resize);
resize();

// ---------- scene assembly (painter's algorithm) ----------
function buildItems(sw){
  const items = [];
  const zRange = R + HALF_H * Math.abs(sinT) + 30;
  const fogOf = z => clamp(0.5 + 0.5 * z / zRange, 0, 1);
  const glowOf = y3 => sw === null ? 0 : Math.exp(-((y3 - sw) * (y3 - sw)) / 3528); // 2*42^2

  // central axis, dashed, depth-sorted with everything else
  const M = 30;
  for (let k = 0; k < M; k += 2){
    const y0 = -HALF_H + (k / M) * 2 * HALF_H;
    const y1 = -HALF_H + ((k + 1) / M) * 2 * HALF_H;
    const a0 = projXY(0, y0, 0), a1 = projXY(0, y1, 0);
    const z = (a0.z + a1.z) / 2;
    items.push({kind:'axis', z, fog:fogOf(z), g:0, px0:a0.x, py0:a0.y, px1:a1.x, py1:a1.y});
  }
  // ruler ticks along the axis, every 5 bp
  for (let i = 0; i < N; i += 5){
    const y3 = (i - (N - 1) / 2) * DY;
    const t = projXY(0, y3, 0);
    items.push({kind:'tick', z:t.z, fog:fogOf(t.z), g:0, x:t.x, y:t.y, u:t.s, major: i % 10 === 0});
  }
  // backbone segments
  for (let st = 0; st < 2; st++){
    const P = st ? pB : pA;
    for (let i = 0; i < N - 1; i++){
      const z = (P[i].z + P[i + 1].z) / 2 - 0.5;
      const ym = (i + 0.5 - (N - 1) / 2) * DY;
      items.push({kind:'seg', st, i, z, fog:fogOf(z), g:glowOf(ym)});
    }
  }
  // base-pair rungs
  for (let i = 0; i < N; i++){
    const z = (pA[i].z + pB[i].z) / 2 - 0.25;
    const y3 = (i - (N - 1) / 2) * DY;
    items.push({kind:'rung', i, z, fog:fogOf(z), g:glowOf(y3)});
  }
  // nucleotide nodes, nudged toward the viewer so they sit on their lines
  for (let st = 0; st < 2; st++){
    const P = st ? pB : pA;
    for (let i = 0; i < N; i++){
      const y3 = (i - (N - 1) / 2) * DY;
      items.push({kind:'node', st, i, z:P[i].z + 1.5, fog:fogOf(P[i].z), g:glowOf(y3)});
    }
  }
  items.sort((a, b) => a.z - b.z);   // far -> near
  return items;
}

function drawItem(it){
  if (it.kind === 'axis'){
    ctx.strokeStyle = `rgba(150,165,175,${(0.07 + 0.13 * it.fog).toFixed(3)})`;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(it.px0, it.py0); ctx.lineTo(it.px1, it.py1); ctx.stroke();

  } else if (it.kind === 'tick'){
    const len = (it.major ? 13 : 7) * it.u;
    ctx.strokeStyle = `rgba(150,165,175,${(0.10 + 0.16 * it.fog).toFixed(3)})`;
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(it.x - len, it.y); ctx.lineTo(it.x + len, it.y); ctx.stroke();

  } else if (it.kind === 'seg'){
    const P = it.st ? pB : pA;
    const p1 = P[it.i], p2 = P[it.i + 1];
    const ph = Math.sin(it.i * 0.55 + (it.st ? 2.1 : 0));
    const alpha = Math.min(1, (0.16 + 0.68 * it.fog) * (0.88 + 0.12 * ph) + 0.32 * it.g);
    ctx.strokeStyle = strandColor(it.st, it.fog, alpha, 3 * ph);
    ctx.lineWidth = (0.9 + 2.2 * it.fog) * (p1.s + p2.s) / 2 + 0.9 * it.g;
    ctx.beginPath(); ctx.moveTo(p1.x, p1.y); ctx.lineTo(p2.x, p2.y); ctx.stroke();

  } else if (it.kind === 'rung'){
    const A = pA[it.i], B = pB[it.i];
    const hov = it.i === hoverIdx;
    const u = (A.s + B.s) / 2;
    const dx = B.x - A.x, dy = B.y - A.y;
    const dist = Math.hypot(dx, dy) || 1;
    const gap = Math.min(4.6 * u, dist * 0.34);       // the two bases meet with a small gap
    const ux = dx / dist, uy = dy / dist;
    const mxp = (A.x + B.x) / 2, myp = (A.y + B.y) / 2;
    const alpha = Math.min(1, (0.26 + 0.52 * it.fog) * (1 + jitter(it.i) * 0.16) + 0.5 * it.g + (hov ? 0.28 : 0));
    ctx.lineWidth = (1.0 + 1.5 * it.fog) * u + 1.5 * it.g + (hov ? 1.1 : 0);
    ctx.strokeStyle = `hsla(${HUE[0]},${SAT[0] - 16}%,${(46 + 13 * it.fog).toFixed(1)}%,${alpha.toFixed(3)})`;
    ctx.beginPath(); ctx.moveTo(A.x, A.y); ctx.lineTo(mxp - ux * gap, myp - uy * gap); ctx.stroke();
    ctx.strokeStyle = `hsla(${HUE[1]},${SAT[1] - 12}%,${(46 + 13 * it.fog).toFixed(1)}%,${alpha.toFixed(3)})`;
    ctx.beginPath(); ctx.moveTo(B.x, B.y); ctx.lineTo(mxp + ux * gap, myp + uy * gap); ctx.stroke();

  } else { // node
    const p = it.st ? pB[it.i] : pA[it.i];
    const hov = it.i === hoverIdx;
    const r = Math.max((3.1 + 3.5 * it.fog) * p.s + 2.1 * it.g + (hov ? 1.3 : 0), 0.6);
    ctx.fillStyle = strandColor(it.st, it.fog, 0.3 + 0.7 * it.fog + 0.4 * it.g,
                                3 * Math.sin(it.i * 0.55 + (it.st ? 2.1 : 0)));
    ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, TAU); ctx.fill();
    if (hov){
      ctx.strokeStyle = 'rgba(226,238,242,0.85)';
      ctx.lineWidth = 1;
      ctx.beginPath(); ctx.arc(p.x, p.y, r + 3.4, 0, TAU); ctx.stroke();
    }
  }
}

function drawBeam(sw){
  const a = projXY(-(R + 18), sw, 0), b = projXY(R + 18, sw, 0);
  const grad = ctx.createLinearGradient(a.x, a.y, b.x, b.y);
  grad.addColorStop(0, 'rgba(150,180,190,0)');
  grad.addColorStop(0.5, 'rgba(150,180,190,0.14)');
  grad.addColorStop(1, 'rgba(150,180,190,0)');
  ctx.strokeStyle = grad;
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
}

// the scan "reads" the pair it crosses and annotates it beside the helix
function drawScanLabel(sw){
  if (sw === null) return;
  const k = Math.round(sw / DY + (N - 1) / 2);
  if (k < 0 || k >= N) return;
  const y3 = (k - (N - 1) / 2) * DY;
  const gk = Math.exp(-((y3 - sw) * (y3 - sw)) / 3528);
  if (gk < 0.05) return;
  const A = pA[k], B = pB[k];
  const [b1, b2] = pairOf(k);
  const mxp = (A.x + B.x) / 2, myp = (A.y + B.y) / 2;
  const extent = R * ((A.s + B.s) / 2) + 14;
  const side = (mxp + extent + 90 <= W - 8) ? 1 : -1;
  const lx = mxp + side * extent;
  const endX = side > 0 ? Math.max(A.x, B.x) : Math.min(A.x, B.x);
  ctx.globalAlpha = Math.min(1, gk * 1.1);
  ctx.strokeStyle = 'rgba(160,175,182,0.4)';
  ctx.lineWidth = 1;
  ctx.beginPath(); ctx.moveTo(endX + side * 6, myp); ctx.lineTo(lx - side * 7, myp); ctx.stroke();
  ctx.font = '11px ' + FONT;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  const w1 = ctx.measureText(b1).width, wd = ctx.measureText('\u2013').width, w2 = ctx.measureText(b2).width;
  let x = side > 0 ? lx : lx - (w1 + 4 + wd + 4 + w2);
  ctx.fillStyle = strandColor(0, 1, 1); ctx.fillText(b1, x, myp); x += w1 + 4;
  ctx.fillStyle = 'rgba(140,155,162,0.9)'; ctx.fillText('\u2013', x, myp); x += wd + 4;
  ctx.fillStyle = strandColor(1, 1, 1); ctx.fillText(b2, x, myp);
  ctx.globalAlpha = 1;
}

function render(sw){
  ctx.fillStyle = BG;
  ctx.fillRect(0, 0, W, H);
  if (gridLayer) ctx.drawImage(gridLayer, 0, 0, W, H);
  if (sw !== null) drawBeam(sw);
  const items = buildItems(sw);
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  for (const it of items) drawItem(it);
  drawScanLabel(sw);
  if (vg){ ctx.fillStyle = vg; ctx.fillRect(0, 0, W, H); }
}

// ---------- interaction ----------
function distToSeg(px, py, ax, ay, bx, by){
  const dx = bx - ax, dy = by - ay;
  const L2 = dx * dx + dy * dy;
  let t = L2 ? ((px - ax) * dx + (py - ay) * dy) / L2 : 0;
  t = clamp(t, 0, 1);
  return Math.hypot(ax + t * dx - px, ay + t * dy - py);
}

function updateHover(){
  hoverIdx = -1;
  if (!hasMouse || dragging || pointers.size > 0) return;
  let best = 26;
  for (let i = 0; i < N; i++){
    const d = distToSeg(mx, my, pA[i].x, pA[i].y, pB[i].x, pB[i].y);
    if (d < best){ best = d; hoverIdx = i; }
  }
}

let lastMsg = '';
const defaultMsg = () => `${N} bp \u00b7 ${(N / 10).toFixed(1)} turns \u00b7 \u03c9 ${rotVel.toFixed(2)} rad/s`;
function updateReadout(sw){
  let msg;
  if (hoverIdx >= 0){
    const [b1, b2] = pairOf(hoverIdx);
    const front = (pA[hoverIdx].z + pB[hoverIdx].z) / 2 >= 0;
    msg = `pair ${String(hoverIdx + 1).padStart(2, '0')} \u00b7 ${b1}\u2013${b2} \u00b7 ${front ? 'front' : 'back'} face`;
  } else if (sw !== null){
    const k = Math.round(sw / DY + (N - 1) / 2);
    if (k >= 0 && k < N){
      const [b1, b2] = pairOf(k);
      msg = `scan \u00b7 pair ${String(k + 1).padStart(2, '0')} \u00b7 ${b1}\u2013${b2}`;
    } else msg = defaultMsg();
  } else msg = defaultMsg();
  if (msg !== lastMsg){ readout.textContent = msg; lastMsg = msg; }
}

canvas.addEventListener('pointerdown', e => {
  canvas.setPointerCapture(e.pointerId);
  pointers.set(e.pointerId, {x: e.clientX, y: e.clientY});
  if (pointers.size === 1){
    dragging = true; lastX = e.clientX; lastY = e.clientY;
    canvas.classList.add('dragging');
  } else if (pointers.size === 2){
    dragging = false;
    rotVel = BASE_SPEED;
    const [a, b] = [...pointers.values()];
    pinchDist = Math.hypot(a.x - b.x, a.y - b.y);
  }
});

canvas.addEventListener('pointermove', e => {
  if (pointers.has(e.pointerId)) pointers.set(e.pointerId, {x: e.clientX, y: e.clientY});
  if (pointers.size === 2){
    const [a, b] = [...pointers.values()];
    const d = Math.hypot(a.x - b.x, a.y - b.y);
    if (pinchDist > 0) zoomTarget = clamp(zoomTarget * d / pinchDist, 0.55, 1.9);
    pinchDist = d;
    return;
  }
  mx = e.clientX; my = e.clientY;
  hasMouse = e.pointerType === 'mouse';
  if (dragging){
    const dx = e.clientX - lastX, dy = e.clientY - lastY;
    lastX = e.clientX; lastY = e.clientY;
    rot += dx * 0.006;
    rotVel = clamp(rotVel * 0.5 + dx * 0.006 * 60 * 0.5, -6, 6);   // flick impulse for inertia
    tiltTarget = clamp(tiltTarget - dy * 0.0045, -0.55, 0.55);     // trackball tilt
  }
});

const endPointer = e => {
  pointers.delete(e.pointerId);
  if (pointers.size < 2) pinchDist = 0;
  if (pointers.size === 0){
    dragging = false;
    canvas.classList.remove('dragging');
  } else if (pointers.size === 1){
    const [p] = [...pointers.values()];
    dragging = true; lastX = p.x; lastY = p.y;
  }
};
canvas.addEventListener('pointerup', endPointer);
canvas.addEventListener('pointercancel', endPointer);
canvas.addEventListener('pointerleave', e => {
  if (e.pointerType === 'mouse'){ hasMouse = false; hoverIdx = -1; }
});

addEventListener('wheel', e => {
  e.preventDefault();
  zoomTarget = clamp(zoomTarget * Math.exp(-e.deltaY * 0.0012), 0.55, 1.9);
}, {passive: false});

// ---------- main loop ----------
let prev = performance.now();
function frame(now){
  const dt = Math.min((now - prev) / 1000, 0.05);
  prev = now;

  if (!dragging){
    rotVel += (BASE_SPEED - rotVel) * (1 - Math.exp(-dt * 1.4));  // inertia eases back to drift
    rot += rotVel * dt;
  }
  tilt += (tiltTarget - tilt) * (1 - Math.exp(-dt * 10));
  zoom += (zoomTarget - zoom) * (1 - Math.exp(-dt * 8));
  sinT = Math.sin(tilt); cosT = Math.cos(tilt);
  sweepT += dt;

  const sw = sweepY(sweepT);
  computePoints();
  updateHover();
  updateReadout(sw);
  render(sw);

  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
})();
</script>
</body>
</html>
